import { useState } from 'react';
import { BaseNode, FieldSelect, NodeInfo } from './BaseNode';
import { BrainCircuit, ChevronDown, ChevronUp } from 'lucide-react';

const MODELS = [
  { value: 'gpt-4o',            label: 'GPT-4o' },
  { value: 'gpt-4o-mini',       label: 'GPT-4o mini' },
  { value: 'gpt-4-turbo',       label: 'GPT-4 Turbo' },
  { value: 'claude-3-5-sonnet', label: 'Claude 3.5 Sonnet' },
  { value: 'claude-3-haiku',    label: 'Claude 3 Haiku' },
  { value: 'gemini-1.5-pro',    label: 'Gemini 1.5 Pro' },
];

const labelStyle = {
  display: 'block',
  fontSize: 10,
  color: '#55556a',
  fontWeight: 600,
  letterSpacing: 0.5,
  textTransform: 'uppercase',
  marginBottom: 4,
};

const pill = (label, value) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 5 }}>
    <span style={{ fontSize: 11, color: '#55556a' }}>{label}</span>
    <span style={{
      fontSize: 11, fontWeight: 600,
      color: '#10b981',
      background: '#10b98115',
      border: '1px solid #10b98130',
      borderRadius: 4,
      padding: '1px 7px',
    }}>{value}</span>
  </div>
);

export const LLMNode = ({ id, data }) => {
  const [model,       setModel]       = useState(data?.model       || 'gpt-4o');
  const [temperature, setTemperature] = useState(data?.temperature ?? 0.7);
  const [maxTokens,   setMaxTokens]   = useState(data?.maxTokens   ?? 1024);
  const [expanded,    setExpanded]    = useState(false);

  return (
    <BaseNode
      id={id}
      title="LLM"
      accentColor="#10b981"
      Icon={BrainCircuit}
      inputs={[
        { id: 'system', label: 'system' },
        { id: 'prompt', label: 'prompt' },
      ]}
      outputs={[{ id: 'response', label: 'response' }]}
      minWidth={240}
    >
      {/* Model selector */}
      <FieldSelect
        label="Model"
        value={model}
        onChange={e => setModel(e.target.value)}
        options={MODELS}
      />

      {/* Temperature slider */}
      <div style={{ marginBottom: 8 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
          <label style={labelStyle}>Temperature</label>
          <span style={{ fontSize: 11, color: '#10b981', fontWeight: 600 }}>{temperature}</span>
        </div>
        <input
          type="range" min="0" max="2" step="0.1"
          value={temperature}
          onChange={e => setTemperature(parseFloat(e.target.value))}
          className="nodrag"
          style={{ width: '100%', accentColor: '#10b981', cursor: 'pointer' }}
        />
        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 2 }}>
          <span style={{ fontSize: 10, color: '#55556a' }}>Precise</span>
          <span style={{ fontSize: 10, color: '#55556a' }}>Creative</span>
        </div>
      </div>

      {/* Expand / collapse advanced */}
      <button
        className="nodrag"
        onClick={() => setExpanded(v => !v)}
        style={{
          width: '100%',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          background: 'transparent',
          border: '1px solid #2a2a3a',
          borderRadius: 6,
          color: '#55556a',
          fontSize: 11,
          padding: '4px 8px',
          cursor: 'pointer',
          marginBottom: expanded ? 8 : 0,
          transition: 'border-color 0.15s, color 0.15s',
          fontFamily: "'Inter', system-ui, sans-serif",
        }}
        onMouseEnter={e => { e.currentTarget.style.borderColor = '#10b981'; e.currentTarget.style.color = '#10b981'; }}
        onMouseLeave={e => { e.currentTarget.style.borderColor = '#2a2a3a'; e.currentTarget.style.color = '#55556a'; }}
      >
        <span>Advanced settings</span>
        {expanded ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
      </button>

      {/* Advanced panel */}
      {expanded && (
        <div style={{
          background: '#0a0a0f',
          border: '1px solid #2a2a3a',
          borderRadius: 6,
          padding: '8px 10px',
        }}>
          {/* Max tokens */}
          <div style={{ marginBottom: 8 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
              <label style={labelStyle}>Max tokens</label>
              <span style={{ fontSize: 11, color: '#10b981', fontWeight: 600 }}>{maxTokens}</span>
            </div>
            <input
              type="range" min="64" max="4096" step="64"
              value={maxTokens}
              onChange={e => setMaxTokens(parseInt(e.target.value))}
              className="nodrag"
              style={{ width: '100%', accentColor: '#10b981', cursor: 'pointer' }}
            />
          </div>
          {/* Summary pills */}
          {pill('Context window', model.startsWith('gpt-4') ? '128k' : model.startsWith('claude') ? '200k' : '1M')}
          {pill('Provider', model.startsWith('gpt') ? 'OpenAI' : model.startsWith('claude') ? 'Anthropic' : 'Google')}
        </div>
      )}
    </BaseNode>
  );
};
